prompt --application/shared_components/user_interface/templates/page/modern_one_page
begin
wwv_flow_imp_shared.create_template(
 p_id=>wwv_flow_imp.id(12237215345942799)
,p_theme_id=>42
,p_name=>'Modern One Page'
,p_static_id=>'modern-one-page'
,p_is_popup=>false
,p_javascript_file_urls=>'#APP_FILES#website-studio/website.js'
,p_javascript_code_onload=>'if (window.wsSite) { wsSite.init(); }'
,p_css_file_urls=>'#APP_FILES#website-studio/website.css'
,p_header_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!DOCTYPE html>',
'<html class="no-js #RTL_CLASS# page-&APP_PAGE_ID!ATTR. app-&APP_ALIAS!ATTR." lang="&BROWSER_LANGUAGE!ATTR." #TEXT_DIRECTION#>',
'<head>',
'  <meta charset="utf-8">',
'  <title>#TITLE#</title>',
'  #APEX_CSS#',
'  #THEME_CSS#',
'  #TEMPLATE_CSS#',
'  #THEME_STYLE_CSS#',
'  #APPLICATION_CSS#',
'  #PAGE_CSS#',
'  #FAVICONS#',
'  #HEAD#',
'  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">',
'</head>',
'<body class="ws-Page #PAGE_CSS_CLASSES#" #TEXT_DIRECTION# #ONLOAD# id="t_PageBody" data-ws-files="#APP_FILES#">',
'<script #APEX_CSP_NONCE_ATTRIBUTE#>(function(b,h){b.classList.add("ws-Loading");var m=/[#&]ws=([^&]*)/.exec(h);if(m){b.className=b.className.split(/\s+/).filter(function(c){return!/^ws-(Design|Accent|Scheme|Font|Header|Corners|Space|Fx|Footer|Ph)--/.'
||'test(c)}).concat(decodeURIComponent(m[1]).split(/[\s+,]+/)).join(" ")}try{var s=b.classList.contains("ws-Fx--theme")&&localStorage.getItem("ws-scheme");if(s){b.classList.remove("ws-Scheme--dark","ws-Scheme--auto");if(s==="dark")b.classList.add("ws-Sc'
||'heme--dark")}}catch(e){}})(document.body,location.hash);</script>',
'<noscript>&APP_TEXT$APEX_PAGE_NOSCRIPT.</noscript>',
'<a href="#main" class="ws-Skip">&APP_TEXT$UI_PAGE_SKIP_TO_CONTENT.</a>',
'#FORM_OPEN#',
'<div class="ws-Progress" aria-hidden="true"></div>',
'<header class="ws-Header" id="ws-header">',
'  <div class="ws-Wrap ws-Header-in">',
'    <div class="ws-Brand-slot">#REGION_POSITION_07#</div>',
'    <a class="ws-Brand ws-Brand-default" href="#HOME_LINK#">#LOGO#</a>',
'    <nav class="ws-Nav" id="ws-nav" aria-label="&APP_TEXT$APEX.TEMPLATE.MAIN_NAV_LABEL!ATTR."></nav>',
'    <div class="ws-Menu-slot">#REGION_POSITION_08#</div>',
'    <div class="ws-Header-end">#AFTER_NAVIGATION_BAR#<button type="button" class="ws-ThemeBtn" aria-pressed="false" aria-label="Dark mode"><span aria-hidden="true"></span></button><button type="button" class="ws-Burger" aria-expanded="false" aria-con'
||'trols="ws-nav" aria-label="Menu"><span></span><span></span><span></span></button></div>',
'  </div>',
'</header>'))
,p_box=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<main id="main" class="ws-Main">',
'  #SUCCESS_MESSAGE##NOTIFICATION_MESSAGE##GLOBAL_NOTIFICATION#',
'  <div class="ws-Hero-slot">#REGION_POSITION_01#</div>',
'  #BODY#',
'</main>',
'<footer class="ws-Footer" id="ws-footer">',
'  <div class="ws-Wrap">',
'    <div class="ws-Footer-grid">#REGION_POSITION_05#</div>',
'    <div class="ws-Footer-bottom">#REGION_POSITION_06#</div>',
'  </div>',
'</footer>',
'<button type="button" class="ws-ToTop" aria-label="Back to top"><span aria-hidden="true">&#8593;</span></button>',
'<a class="ws-Chat" href="https://wa.me/&WHATSAPP_NUMBER." data-number="&WHATSAPP_NUMBER." target="_blank" rel="noopener" aria-label="WhatsApp"><span class="fa fa-whatsapp" aria-hidden="true"></span></a>',
'<div class="ws-Dialogs" id="t_Body_inlineDialogs">#REGION_POSITION_04#</div>'))
,p_footer_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#FORM_CLOSE#',
'#DEVELOPER_TOOLBAR#',
'#APEX_JAVASCRIPT#',
'#GENERATED_CSS#',
'#THEME_JAVASCRIPT#',
'#TEMPLATE_JAVASCRIPT#',
'#APPLICATION_JAVASCRIPT#',
'#PAGE_JAVASCRIPT#',
'#GENERATED_JAVASCRIPT#',
'</body>',
'</html>'))
,p_success_message=>'<div class="ws-Alert" id="t_Alert_Success" role="status"><h2 class="u-vh">#SUCCESS_MESSAGE_HEADING#</h2>#SUCCESS_MESSAGE#</div>'
,p_notification_message=>'<div class="ws-Alert ws-Alert--warning" id="t_Alert_Notification" role="alert"><h2 class="u-vh">#ERROR_MESSAGE_HEADING#</h2>#MESSAGE#</div>'
,p_theme_class_id=>8
,p_default_template_options=>'ws-Fx--sticky:ws-Fx--reveal:ws-Fx--count:ws-Fx--top'
,p_error_page_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="ws-Alert ws-Alert--warning">',
'  <h1>#MESSAGE#</h1>',
'  <p>#ADDITIONAL_INFO#</p>',
'  <div>#TECHNICAL_INFO#</div>',
'  <p><button class="a-Error-back t-Button t-Button--hot" type="button">#OK#</button></p>',
'</div>'))
,p_grid_type=>'FIXED'
,p_grid_max_columns=>12
,p_grid_always_use_max_columns=>true
,p_grid_has_column_span=>true
,p_grid_always_emit=>true
,p_grid_emit_empty_leading_cols=>true
,p_grid_emit_empty_trail_cols=>false
,p_grid_default_label_col_span=>2
,p_grid_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="ws-Grid">',
'#ROWS#',
'</div>'))
,p_grid_row_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="ws-Row #CSS_CLASSES#">',
'#COLUMNS#',
'</div>'))
,p_grid_column_template=>'<div class="ws-Col ws-Col--#COLUMN_SPAN_NUMBER# #CSS_CLASSES# #FIRST_LAST_COLUMN_ATTRIBUTES#" #ATTRIBUTES#>#CONTENT#</div>'
,p_grid_first_column_attributes=>'col-start'
,p_grid_last_column_attributes=>'col-end'
,p_template_comment=>'Modern One Page (Website Studio) - a one-page website. The header menu is a Website - Menu list region in the Menu slot, or else it is built from the sections (Modern Section regions with Show in Menu); the hero goes in the Hero slot, the footer colu'
||'mns in Footer. CSS and JavaScript come from the static files website-studio/website.css and website.js.'
);
