wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(12253380757942944)
,p_plug_name=>'Website Studio'
,p_static_id=>'hero'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="wss-Hero">',
'  <h1>One-page and multi-page websites for Oracle APEX</h1>',
'  <p>A page template, a section template, a menu template and 23 report templates - hero sliders, services, numbers, team, testimonials, clients, pricing, news, products and menus, photo galleries, events, opening hours, comparisons, videos, maps and'
||' more. Every list comes from a SQL query. 15 designs, 10 accent colours, light and dark, 7 typefaces including Arabic, right-to-left ready. Every look is a template option. Start from a website below, fine-tune it in the Designer, copy the templates '
||'into your app.</p>',
'  <a class="t-Button t-Button--hot" href="f?p=&APP_ID.:DESIGNER:&APP_SESSION."><span class="t-Button-label">Open the Designer</span></a>',
'  <a class="t-Button wss-Ghost" href="f?p=&APP_ID.:WEBSITE:&APP_SESSION." target="_blank" rel="noopener"><span class="t-Button-label">See the demo website</span></a>',
'  <a class="t-Button wss-Ghost" href="f?p=&APP_ID.:HOW-TO-USE:&APP_SESSION."><span class="t-Button-label">How to use it</span></a>',
'</div>',
'<h2 class="wss-H2">Starter Websites</h2>',
'<p class="wss-Sub">8 complete websites with their own content, menu and photos. Open one, or customize it in the Designer.</p>',
'<div class="wss-Grid" id="wss-sites"></div>',
'<h2 class="wss-H2">Multi-page Websites</h2>',
'<p class="wss-Sub">4 websites with several pages that share one menu, header and footer. The menu links to pages, and inner pages open with a page title.</p>',
'<div class="wss-Grid" id="wss-multi"></div>',
'<h2 class="wss-H2">Looks</h2>',
'<p class="wss-Sub">27 ready-made looks on the demo website. Each one works on every starter website.</p>',
'<div class="wss-Filter" role="group" aria-label="Filter">',
'  <button type="button" data-f="" aria-pressed="true">All</button>',
'  <button type="button" data-f="light" aria-pressed="false">Light</button>',
'  <button type="button" data-f="clean" aria-pressed="false">Clean</button>',
'  <button type="button" data-f="editorial" aria-pressed="false">Editorial</button>',
'  <button type="button" data-f="bold" aria-pressed="false">Bold</button>',
'  <button type="button" data-f="dark" aria-pressed="false">Dark</button>',
'  <button type="button" data-f="midnight" aria-pressed="false">Midnight</button>',
'  <button type="button" data-f="glass" aria-pressed="false">Glass</button>',
'  <button type="button" data-f="soft" aria-pressed="false">Soft UI</button>',
'  <button type="button" data-f="minimal" aria-pressed="false">Minimal</button>',
'  <button type="button" data-f="corporate" aria-pressed="false">Corporate</button>',
'  <button type="button" data-f="saas" aria-pressed="false">SaaS</button>',
'  <button type="button" data-f="luxury" aria-pressed="false">Elegant</button>',
'  <button type="button" data-f="playful" aria-pressed="false">Playful</button>',
'  <button type="button" data-f="organic" aria-pressed="false">Organic</button>',
'  <button type="button" data-f="techgrid" aria-pressed="false">Tech Grid</button>',
'  <button type="button" data-f="swiss" aria-pressed="false">Swiss</button>',
'  <button type="button" data-f="retro" aria-pressed="false">Retro</button>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
